<?php
function workflow_hidden($action,$extra=[]){echo '<input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="'.e($action).'">';foreach($extra as $k=>$v)echo '<input type="hidden" name="'.e($k).'" value="'.e($v).'">';}
function workflow_form($kind){
 $permission=['Manual Outflow'=>'manual_outflow','Borrow Issue'=>'borrow_issue','Non-Sellable Release'=>'nonsellable_out','Platform Transfer'=>'transfer_platform'][$kind];if(!can_action($permission))return;
 $editId=(int)($_SESSION['workflow_edit_'.$kind]??0);$edit=$editId?workflow_batch($editId):null;if($edit){workflow_owner($edit);if($edit['status']!=='Review'){unset($_SESSION['workflow_edit_'.$kind]);$editId=0;$edit=null;}}$initial=$edit['workflow']['data']??[];
 $title=['Borrow Issue'=>'Issue Borrowed Products','Non-Sellable Release'=>'Physical Release from Non-Sellable','Platform Transfer'=>'New Platform Stock Transfer'][$kind]??$kind;$prefix=['Borrow Issue'=>'BOR','Non-Sellable Release'=>'NSR','Platform Transfer'=>'PTR'][$kind]??'OUT';
 echo '<div class="card batch-form"><h3>'.e($title).'</h3>';if($kind==='Manual Outflow')echo '<p><a class="btn ghost" href="?page=warranty">Warranty Replacement</a> uses the original defective return record.</p>';
 echo '<form method="post" action="actions.php" enctype="multipart/form-data" data-batch-form data-initial="'.e(json_encode($initial)).'">';workflow_hidden('batch_prepare',['kind'=>$kind,'return'=>['Borrow Issue'=>'borrowed','Non-Sellable Release'=>'restricted_release','Platform Transfer'=>'transfers'][$kind]??'outflow&platform=Manual','batch_nonce'=>bin2hex(random_bytes(16)),'editing_batch_id'=>$editId,'editing_digest'=>$edit['workflow']['digest']??'']);
 echo '<div class="batch-fields"><label>'.($kind==='Borrow Issue'?'Issue Date':'Date').'<input type="date" name="txn_date" value="'.date('Y-m-d').'" max="'.date('Y-m-d').'" required></label>';
 if($kind==='Borrow Issue')echo '<label>Borrower<input name="borrower" maxlength="150" required></label><label>Department / Business Unit<input name="department" maxlength="150" required></label><label>Expected Return Date<input type="date" name="due_date" min="'.date('Y-m-d').'" required></label>';
 if(in_array($kind,['Manual Outflow','Non-Sellable Release'],true)){echo '<label>Purpose / Transaction Type<select name="type">';foreach($kind==='Manual Outflow'?['Transfer Out','Direct Sale','Internal Use','Marketing','Sponsorship','Freebie','Supplier Return']:['Disposal','Return to Supplier','Rework','Repackaging'] as $type)echo '<option>'.e($type).'</option>';echo '</select></label>';}
 echo '<label>'.($kind==='Borrow Issue'?'Borrow Reference':($kind==='Platform Transfer'?'Transfer Reference':'Reference / DR Number')).'<input name="reference_no" value="'.($kind==='Manual Outflow'?'':e(next_ref($prefix))).'" maxlength="100" required></label>';
 if($kind==='Manual Outflow')echo '<label>Recipient / Business Unit<input name="recipient" maxlength="150" required></label>';
 if($kind==='Platform Transfer'){echo '<label>Products / SKU'.picker('product_id','Type product name or SKU...',true,'',false).'</label>';foreach(['from_platform'=>'From Platform','to_platform'=>'To Platform'] as $field=>$label){echo '<label>'.$label.'<select name="'.$field.'">';foreach($field==='from_platform'?['Lazada','Shopee','TikTok']:['Shopee','Lazada','TikTok'] as $p)echo '<option>'.$p.'</option>';echo '</select></label>';}echo '<label>Quantity<input type="number" name="qty" min="1" step="1" required></label>';}
 if($kind!=='Manual Outflow')echo '<label class="batch-wide">'.($kind==='Borrow Issue'?'Purpose / Reason':'Required Reason').'<input name="reason" minlength="3" maxlength="2000" required></label>';
 if(in_array($kind,['Manual Outflow','Non-Sellable Release'],true))echo '<label class="batch-wide">Batch Attachment · Optional<input type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg"></label>';
 echo '</div>';
 if($kind!=='Platform Transfer'){
  echo '<p class="muted small">'.($kind==='Non-Sellable Release'?'Only the linked Non-Sellable and physical quantities decrease after separate Admin approval.':'Automatic stock source: largest available sellable allocation first. Review the platform breakdown before posting.').'</p><div class="batch-entry-table"><table class="table"><thead><tr><th>'.($kind==='Non-Sellable Release'?'Original Restricted Source / Product':'Products / SKU').'</th><th>Available</th><th>Quantity</th><th></th></tr></thead><tbody data-batch-lines><tr data-batch-line><td>';
  if($kind==='Non-Sellable Release'){echo '<select name="items[0][source_id]" data-product-select data-release-source required><option value="">Select original source...</option>';foreach(db()->query('SELECT n.*,p.name,p.master_sku FROM non_sellable n JOIN products p ON p.id=n.product_id WHERE n.reversed_by_request IS NULL ORDER BY n.id DESC') as $r){$remaining=(int)$r['qty']-release_total($r['id']);if($remaining>0)echo '<option value="'.$r['id'].'" data-available="'.$remaining.'">'.e('NS-'.$r['id'].' · '.$r['name'].' · '.$r['master_sku'].' · '.$r['condition_type'].' · '.$remaining.' pcs').'</option>';}echo '</select>';}
  else echo picker('items[0][product_id]','Type product name or SKU...',true,'',false);
  echo '</td><td><span data-batch-available>—</span></td><td><input type="number" min="1" step="1" name="items[0][qty]" required></td><td><button type="button" class="btn ghost" data-batch-remove>Remove</button></td></tr></tbody></table></div><button type="button" class="btn ghost" data-batch-add>+ Add Item Line</button>';
 }
 echo '<div class="modal-actions"><button type="reset" class="btn ghost">Clear Form</button><button class="btn primary">Validate &amp; Review</button></div></form></div>';
}
function workflow_history($kind){$offset=max(0,(int)($_GET['batch_offset']??0));$size=10;$q=db()->prepare('SELECT * FROM import_batches WHERE import_type=? ORDER BY id DESC LIMIT 10 OFFSET '.$offset);$q->execute([$kind]);echo '<div class="card table-wrap"><h3>'.e($kind).' History</h3><table class="table"><tr><th>Date / Reference</th><th>Items / Quantity</th><th>Status</th><th></th></tr>';foreach($q as $b){$w=json_decode($b['result_json'],true)['workflow']??[];echo '<tr><td>'.e(($w['data']['txn_date']??'').' · '.($w['data']['ref']??'')).'</td><td>'.(int)$b['rows_read'].' items · '.(int)$b['units'].' posted pcs</td><td>'.e($b['status']).'</td><td><a class="btn ghost" href="?page=stock_batch&id='.$b['id'].'">View</a></td></tr>';}echo '</table></div>';echo rs8_pagination(rs8_list_total('SELECT COUNT(*) FROM import_batches WHERE import_type=?',[$kind]),$offset,10,$_GET,'batch_offset');}
function workflow_page($id){
 $b=workflow_batch($id);$w=$b['workflow'];$data=$w['data'];usability_journey($b['status'],match($b['import_type']){'Platform Transfer'=>'Platform allocations change; total physical stock stays unchanged.','Non-Sellable Release'=>'Non-Sellable and total physical stock decrease; sellable stock is unchanged.',default=>'Sellable stock decreases using the source platform quantities shown below.'},'#workflowHistory',$b['import_type']==='Non-Sellable Release');echo '<div class="page-head"><div><h1>'.e($b['import_type']).'</h1><p>'.e($data['ref']).' · '.e($data['txn_date']).' · '.e($b['status']).'</p></div></div><div class="card"><p>Prepared by '.e(rs8_user_name($b['user_id'])).'</p>';
 foreach(['borrower'=>'Borrower','department'=>'Department','due_date'=>'Due Date','type'=>'Purpose','recipient'=>'Recipient','reason'=>'Reason'] as $field=>$label)if(!empty($data[$field]))echo '<p>'.e($label.': '.$data[$field]).'</p>';
 if(!empty($w['posted_by']))echo '<p>Posted / Approved by '.e($w['posted_by']['name'].' · '.$w['posted_at']).'</p>';
 echo '<div class="modal-actions"><a class="btn ghost" href="batch_document.php?id='.$id.'&format=xlsx">Download Excel</a><a class="btn ghost" target="_blank" href="batch_document.php?id='.$id.'&format=print">Print / PDF</a>';if($b['stored_path'])echo '<a class="btn ghost" target="_blank" href="batch_document.php?id='.$id.'">View Batch Attachment</a>';echo '</div></div>';
 echo '<div class="card table-wrap"><h3>'.($b['status']==='Posted'?'Recorded Quantities':'Validation & Stock Breakdown').'</h3><table class="table"><tr><th>Products / SKU</th><th>Available at Review</th><th>Quantity</th><th>Source / Platform Breakdown</th><th>After</th></tr>';
 foreach($w['plan'] as $line){echo '<tr><td>'.e($line['name']).'<br>'.e($line['sku']).'</td><td>'.(int)$line['available'].'</td><td>'.(int)$line['qty'].'</td><td>';if($b['import_type']==='Non-Sellable Release')echo e('NS-'.$line['source_id'].' · '.$line['condition'].' · '.$line['source_ref']);elseif($b['import_type']==='Platform Transfer')echo e($data['from'].' → '.$data['to']);else foreach($line['split'] as $p=>$qty)if($qty)echo e($p).': −'.(int)$qty.'<br>';echo '</td><td>'.(int)$line['remaining'].'</td></tr>';}echo '</table></div>';
 if($b['import_type']==='Platform Transfer'){echo '<div class="card"><table class="table"><tr><th>Platform</th><th>Before</th><th>Change</th><th>After</th></tr>';foreach($w['plan'][0]['before'] as $platform=>$qty){$delta=$platform===$data['from']?-$w['plan'][0]['qty']:($platform===$data['to']?$w['plan'][0]['qty']:0);echo '<tr><td>'.e($platform).'</td><td>'.$qty.'</td><td>'.sprintf('%+d',$delta).'</td><td>'.($qty+$delta).'</td></tr>';}echo '<tr><td>Total Physical</td><td>'.$w['plan'][0]['physical_before'].'</td><td>0</td><td>'.$w['plan'][0]['physical_before'].'</td></tr></table></div>';}
 if($b['import_type']==='Non-Sellable Release')echo '<p class="muted">Only Non-Sellable and physical stocks decrease. Sellable and platform allocations remain unchanged.</p>';
 if($b['status']==='Review'&&can_action(['Borrow Issue'=>'borrow_issue','Non-Sellable Release'=>'nonsellable_out','Platform Transfer'=>'transfer_platform'][$b['import_type']]??'manual_outflow')&&(current_user()['role']==='Admin'||(int)$b['user_id']===current_user()['id'])){echo '<div class="card"><form method="post" action="actions.php">';workflow_hidden($b['import_type']==='Non-Sellable Release'?'batch_submit':'batch_post',['batch_id'=>$id,'digest'=>$w['digest'],'return'=>'stock_batch&id='.$id]);echo '<label class="ack"><input type="checkbox" name="review_ack" value="1" required> I reviewed the products, quantities, source deductions and physical movement.</label><button class="btn primary">'.($b['import_type']==='Non-Sellable Release'?'Submit for Separate Admin Approval':'Confirm & Post').'</button></form><form method="post" action="actions.php">';workflow_hidden('batch_refresh',['batch_id'=>$id,'return'=>'stock_batch&id='.$id]);echo '<button class="btn ghost">Refresh Validation</button></form><form method="post" action="actions.php">';workflow_hidden('batch_edit',['batch_id'=>$id]);echo '<button class="btn secondary">Back to Edit Items</button></form></div>';}
 if($b['status']==='Submitted'){echo '<div class="alert warn">Awaiting a different Admin. No physical release has been posted.</div>';if(current_user()['role']==='Admin'&&(int)$b['user_id']!==current_user()['id']){echo '<div class="card"><form method="post" action="actions.php">';workflow_hidden('batch_post',['batch_id'=>$id,'digest'=>$w['digest'],'return'=>'stock_batch&id='.$id]);echo '<label class="ack"><input type="checkbox" name="review_ack" value="1" required> I approve the actual physical release and all source quantities.</label><button class="btn primary">Approve & Post Physical Release</button></form><form method="post" action="actions.php">';workflow_hidden('batch_return',['batch_id'=>$id,'return'=>'stock_batch&id='.$id]);echo '<label>Reason for Return<input name="reason" minlength="3" required></label><button class="btn ghost">Return for Correction</button></form></div>';}}
 if(in_array($b['status'],['Review','Submitted'],true)&&(current_user()['role']==='Admin'||(int)$b['user_id']===current_user()['id'])&&can_action('manual_outflow')){echo '<div class="card"><form method="post" action="actions.php">';workflow_hidden('batch_cancel',['batch_id'=>$id,'return'=>'stock_batch&id='.$id]);echo '<label>Cancellation Reason<input name="reason" minlength="3" required></label><button class="btn ghost">Cancel Batch</button></form></div>';}
 if(!empty($w['borrow_id']))echo '<a class="btn ghost" href="?page=borrowed&id='.(int)$w['borrow_id'].'">Open Borrow Record & Returns</a>';
 echo '<div class="card table-wrap" id="workflowHistory" data-tour="history"><h3>Permanent Batch History</h3><table class="table"><tr><th>Date</th><th>Event</th><th>User</th><th>Details</th></tr>';foreach($w['events'] as $event)echo '<tr><td>'.e($event['at']).'</td><td>'.e($event['event']).'</td><td>'.e($event['by']['name']).'</td><td>'.e($event['details']).'</td></tr>';echo '</table></div>';
}
function rs8_user_name($id){$q=db()->prepare('SELECT name FROM users WHERE id=?');$q->execute([(int)$id]);return (string)$q->fetchColumn();}
function current_stocks_batch_page(){
 global $brandProducts,$products,$selectedBrand,$selectedMain,$selectedSub,$brandQuery;$status=$_GET['status']??'';$q=norm($_GET['q']??'');
 echo '<div class="page-head"><div><h1>Current Stocks</h1><p>Read-only consolidated result of all inventory movements.</p></div><div class="modal-actions"><a class="btn ghost" href="?page=inventory_count">Inventory Count History</a>';if(can_action('upload_inventory_count'))echo '<button type="button" class="btn secondary" data-toggle-count>Prepare Inventory Count</button>';echo '</div></div>';
 usability_terms();echo '<div class="toolbar card compact"><form method="get" class="inline-form product-list-filters"><input type="hidden" name="page" value="stocks"><label>Products / SKU<input name="q" data-product-list-search value="'.e($_GET['q']??'').'" placeholder="Type product name or SKU..."></label>'.inventory_brand_select($products,$selectedBrand).inventory_category_select($selectedMain,$selectedSub).'<label>Status<select name="status"><option value="">All Statuses</option>';foreach(['in'=>'In Stock','low'=>'Low Stock','out'=>'Out of Stock','negative'=>'Reconcile'] as $v=>$label)echo '<option value="'.$v.'" '.($status===$v?'selected':'').'>'.$label.'</option>';echo '</select></label><button class="btn secondary">Filter</button>'.inventory_clear_filter_link().'</form></div>';
 if(can_action('upload_inventory_count')){echo '<section class="card" id="stockCountTools" hidden><h3>Prepare Inventory Count</h3><form method="post" action="inventory_count.php" class="stack">';workflow_hidden('create');foreach(['brand','main_category','subcategory','q','status'] as $key)echo '<input type="hidden" name="'.$key.'" value="'.e($_GET[$key]??'').'">';echo '<div class="batch-fields"><label>Count Date<input type="date" name="count_date" value="'.date('Y-m-d').'" max="'.date('Y-m-d').'" required></label><label>Count Scope<select name="count_scope"><option value="Sellable">Sellable Only</option><option value="All Conditions">All Stock Conditions</option></select></label></div><label class="ack"><input type="checkbox" name="cutoff_ack" value="1" required> Counts represent the selected cutoff. Movements during counting have been accounted for.</label><div class="modal-actions"><button class="btn secondary">Create Final Count &amp; Download Sheet</button></div></form></section>';}
 echo '<div class="card table-wrap"><table class="table"><tr><th>Master SKU</th><th>Product</th><th>Brand</th><th>Beginning</th><th>Sellable On Hand</th><th>Reserved</th><th>Available</th><th>Non-Sellable</th><th>Total Physical</th><th>Status</th><th></th></tr>';
 foreach($brandProducts as $p){if($q&&!str_contains(norm($p['name'].' '.$p['brand'].' '.$p['master_sku']),$q))continue;$s=stock_row($p['id']);$st=detect_status($s['current'],$p['low_stock_threshold']??10);if($status!==''&&stock_status_key($st[0])!==$status)continue;echo '<tr><td>'.e($p['master_sku']).'</td><td>'.e($p['name']).'<br><span class="muted small">'.e($p['category']).'</span></td><td>'.e(inventory_filter_brand($p['brand'])).'</td><td>'.$s['beginning'].'</td><td>'.$s['current'].'</td><td>'.$s['reserved'].'</td><td>'.$s['available'].'</td><td>'.$s['nonsellable'].'</td><td>'.$s['physical'].'</td><td>'.badge($st[0],$st[1]).'</td><td><a class="btn ghost sm" href="?page=product_detail&id='.$p['id'].'">View</a></td></tr>';}
 echo '</table></div>';
}
function receiving_page($id=0){
 echo '<h2>Manual Inflow</h2>';
 if($id){$b=return_batch($id);$a=return_analysis($b);usability_journey($b['status'],'Physically received units increase sellable or Non-Sellable stock according to each item condition. Total physical stock increases.','?page=inflow&history=all',return_requires_admin_review($a));echo '<div class="card"><h3>'.e($b['batch_ref']).' · '.e($b['status']).'</h3>';if($b['stored_path'])echo '<a class="btn ghost" target="_blank" href="batch_document.php?type=return&id='.$id.'">View Batch Attachment</a>';echo '<table class="table"><tr><th>Platform / Order</th><th>Products / SKU</th><th>Received</th><th>Condition</th><th>Remaining / Validation</th></tr>';foreach($a['rows'] as $r)echo '<tr><td>'.e($r['platform'].' / '.$r['order']).'</td><td>'.e(($r['product_name']??$r['item']).' · '.($r['sku']??'')).'</td><td>'.(int)$r['qty'].'</td><td>'.e($r['condition']).'</td><td>'.e($r['errors']?implode(' · ',$r['errors']):($r['remaining_after']??'Posted')).'</td></tr>';echo '</table>';foreach($a['warnings'] as $warning)echo '<p class="alert warn">'.e($warning).'</p>';
  if($b['status']==='Review'&&can_action('return_confirm')&&(current_user()['role']==='Admin'||(int)$b['created_by']===current_user()['id'])){if(!$a['errors']&&return_uploader_allowed($b,$a)){echo '<form method="post" action="actions.php">';workflow_hidden('receiving_post',['batch_id'=>$id,'digest'=>$a['digest'],'return'=>'manual_receiving&id='.$id]);echo '<label class="ack"><input type="checkbox" name="review_ack" value="1" required> I confirm the actual received items, quantities and conditions; similar receipts were checked.</label><button class="btn primary">Confirm & Post</button></form>';}elseif(return_requires_admin_review($a))echo '<div class="alert warn">A similar prior receipt requires Admin review before posting.</div>';echo '<form method="post" action="actions.php">';workflow_hidden('receiving_edit',['batch_id'=>$id]);echo '<button class="btn secondary">Back to Edit Items</button></form><form method="post" action="actions.php">';workflow_hidden('receiving_cancel',['batch_id'=>$id,'return'=>'manual_receiving&id='.$id]);echo '<button class="btn ghost">Cancel Unposted Batch</button></form>';}echo '</div>';return;
 }
 if(!can_action('return_confirm')){echo '<p>Return receiving access is required.</p>';return;}$c=receiving_cart();echo '<div class="card"><form method="post" enctype="multipart/form-data" action="actions.php">';workflow_hidden('receiving_lookup',['return'=>'inflow&entry=manual']);echo '<div class="batch-fields"><label>Transaction Type<select name="transaction_kind">';foreach(['returns'=>'Return Orders','cancelled'=>'Cancelled Orders'] as $v=>$label)echo '<option value="'.$v.'" '.($c['kind']===$v?'selected':'').'>'.$label.'</option>';echo '</select></label><label>Received Date<input type="date" name="txn_date" value="'.e($c['date']).'" max="'.date('Y-m-d').'" required></label><label>One Batch Attachment · Optional<input type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg"></label><label>Platform<select name="platform"><option>Shopee</option><option>Lazada</option><option>TikTok</option></select></label><label>Original Order ID<input name="order_id" maxlength="100"></label><div class="modal-actions"><button class="btn secondary">Find Order Items</button></div></div>';if(!empty($c['attachment_name']))echo '<p>Batch attachment retained: '.e($c['attachment_name']).'</p>';
 foreach($c['orders'] as $key=>$order){echo '<div class="card receiving-order"><div class="card-head"><h3>'.e($order['platform'].' · Order '.$order['order']).'</h3><button class="btn ghost" name="remove_order" value="'.e($key).'">Remove Order</button></div><div class="batch-entry-table"><table class="table"><tr><th>Receive</th><th>Products / SKU</th><th>Ordered</th><th>Already Received</th><th>Remaining</th><th>Receive Qty</th><th>Condition</th></tr>';foreach($order['items'] as $item){$k=cancelled_order_line_key($order['platform'],$order['order'],$item['product_id']);echo '<tr><td><input type="checkbox" name="lines['.$k.'][selected]" value="1" '.(!empty($item['selected'])?'checked':'').' '.($item['remaining']<1?'disabled':'').'></td><td>'.e($item['name']).'<br>'.e($item['sku']).'</td><td>'.$item['original'].'</td><td>'.$item['returned'].'</td><td>'.$item['remaining'].'</td><td><input type="number" min="1" max="'.max(1,$item['remaining']).'" step="1" name="lines['.$k.'][qty]" value="'.e($item['qty']).'"></td><td><select name="lines['.$k.'][condition]">';foreach(['Good Item'=>'Sellable','Damaged / Leak'=>'Damaged / Leak','For Repackaging'=>'For Repackaging'] as $v=>$label)echo '<option value="'.e($v).'" '.($item['condition']===$v?'selected':'').'>'.$label.'</option>';echo '</select></td></tr>';}echo '</table></div></div>';}
 echo '<label class="ack"><input type="checkbox" name="physical_ack" value="1"> The selected items were physically received.</label><div class="modal-actions"><button class="btn ghost" formaction="actions.php" name="receiving_clear" value="1">Clear Batch</button><button class="btn primary" name="receiving_validate" value="1">Validate & Review</button></div></form></div>';
}
